23	// Rollup derives a read-only view of the roller whose windows are factor
24	// times wider than the roller's own, aligned to integer multiples of the
25	// coarser size since the Unix epoch, left-closed and right-open exactly
26	// like the roller's windows. Each coarse window merges the statistics of
27	// the roller windows it covers: counts and sums add, minimums take the
28	// smaller, maximums take the larger. A factor of 1 yields a view
29	// window-for-window identical to the roller's own.
30	//
31	// Rollup panics with "rollup: bad factor" if factor is not positive, or if
32	// factor times the roller's window width overflows the range of a
33	// nanosecond duration: a wrapped coarse width could not align windows to
34	// the epoch. It is a pure read: the roller's statistics and its most-recent
35	// marker are untouched, and concurrent adds, batches, backfills, and merges
36	// proceed as usual — the view observes one consistent snapshot of the
37	// roller.
38	func (r *Roller) Rollup(factor int) *View {
39		if factor <= 0 {
40			panic("rollup: bad factor")
41		}
42		if int64(factor) > math.MaxInt64/r.window.Nanoseconds() {
43			panic("rollup: bad factor")
44		}
45		coarse := time.Duration(factor) * r.window
46		w := coarse.Nanoseconds()
47	
48		r.mu.RLock()
49		defer r.mu.RUnlock()
50		fine := r.buckets
51		if len(r.back) != 0 {
52			fine = mergeWindows(r.buckets, r.back)
53		}
54		// The coarse start is monotone in the fine start, so covered windows
55		// are consecutive and the whole derivation is one linear pass with a
56		// single output allocation bounded by the number of fine windows.
57		windows := make([]Window, 0, len(fine))
58		for _, f := range fine {
59			start := alignStart(f.Start, w)
60			if n := len(windows); n != 0 && windows[n-1].Start.Equal(start) {
61				cur := &windows[n-1]
62				cur.Count = satAdd(cur.Count, f.Count)
63				cur.Sum += f.Sum
64				if f.Min < cur.Min {
65					cur.Min = f.Min
66				}
67				if f.Max > cur.Max {
68					cur.Max = f.Max
69				}
70			} else {
71				windows = append(windows, Window{
72					Start: start,
73					Count: f.Count,
74					Sum:   f.Sum,
75					Min:   f.Min,
76					Max:   f.Max,
77				})
78			}
79		}
80		return &View{window: coarse, windows: windows}
81	}
82	
