84	// the same exact-match rule as the roller's Window. A start no coarse
85	// window begins at yields the zero Window and no error; whether the window
86	// exists is told from its sample count. The returned Window is a copy and
87	// stays valid no matter what is filed into the roller afterwards.
88	func (v *View) Window(start time.Time) Window {
89		if i, ok := windowIndex(v.windows, start); ok {
90			return v.windows[i]
91		}
92		return Window{}
93	}
94	
