167			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
168			return 1
169		}
170		return 0
171	}
172	
173	// argError writes one command-line usage diagnostic.
174	func argError(stderr io.Writer, format string, a ...any) {
175		fmt.Fprintf(stderr, "rollupctl: "+format+"\n", a...)
176	}
177	
178	// parseArgs extracts the subcommand and the flag values. Flags may stand
179	// on either side of the subcommand, Go-style: --name value, --name=value,
180	// with one or two leading dashes.
181	func parseArgs(args []string, stderr io.Writer) (command, bool) {
182		fail := func(format string, a ...any) (command, bool) {
183			argError(stderr, format, a...)
184			return command{}, false
185		}
186		var cmd command
187		sub := ""
188		flagsEnded := false
189		for i := 0; i < len(args); i++ {
190			a := args[i]
191			if !flagsEnded && a == "--" {
192				flagsEnded = true
193				continue
194			}
195			if flagsEnded || !strings.HasPrefix(a, "-") || a == "-" {
196				if sub != "" || (a != "windows" && a != "range" && a != "merge") {
197					return fail("unexpected argument %q", a)
198				}
199				sub = a
200				continue
201			}
202			name := a[1:]
203			if strings.HasPrefix(name, "-") {
204				name = name[1:]
205			}
206			value := ""
207			inline := false
208			if k := strings.IndexByte(name, '='); k >= 0 {
209				value = name[k+1:]
210				name = name[:k]
211				inline = true
212			}
213			switch name {
214			case "file", "window", "from", "to":
215				if !inline {
216					i++
217					if i >= len(args) {
218						return fail("flag --%s needs a value", name)
219					}
220					value = args[i]
221				}
222				if value == "" {
223					return fail("flag --%s needs a value", name)
224				}
225				switch name {
226				case "file":
227					cmd.files = append(cmd.files, value)
228				case "window":
229					cmd.window = value
230				case "from":
231					cmd.from, cmd.hasFrom = value, true
232				case "to":
233					cmd.to, cmd.hasTo = value, true
234				}
235			default:
236				return fail("unexpected argument %q", a)
237			}
238		}
239		cmd.sub = sub
240		if sub == "" {
241			return fail("expected a subcommand: windows, range, or merge")
242		}
243		if len(cmd.files) == 0 {
244			return fail("--file is required")
245		}
246		switch sub {
247		case "merge":
248			if cmd.hasFrom || cmd.hasTo {
249				return fail("--from and --to belong to the range subcommand")
250			}
251			if len(cmd.files) != 2 {
252				return fail("merge takes exactly two --file arguments, got %d", len(cmd.files))
253			}
254		case "range":
255			if len(cmd.files) != 1 {
256				return fail("range takes exactly one --file argument, got %d", len(cmd.files))
257			}
258			if !cmd.hasFrom {
259				return fail("--from is required")
260			}
261			if !cmd.hasTo {
