275	// ingestFile opens one input file and streams its samples into a fresh
276	// roller. It returns a non-zero exit code after writing one diagnostic if
277	// the file cannot be opened or its contents are invalid.
278	func ingestFile(path string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
279		info, err := os.Stat(path)
280		if err != nil {
281			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
282			return nil, 3
283		}
284		if info.IsDir() {
285			fmt.Fprintf(stderr, "rollupctl: %s: is a directory\n", path)
286			return nil, 3
287		}
288		f, err := os.Open(path)
289		if err != nil {
290			fmt.Fprintf(stderr, "rollupctl: %s\n", err)
291			return nil, 3
292		}
293		roller, code := ingest(f, path, d, stderr)
294		f.Close()
295		if code != 0 {
296			return nil, code
297		}
298		return roller, 0
299	}
300	
301	// ingest streams the samples from in into a fresh roller. On any content
302	// problem it returns code 4 after writing one diagnostic naming the file
303	// and line; no sample lines are printed by the caller in that case.
304	func ingest(in io.Reader, name string, d time.Duration, stderr io.Writer) (*rollup.Roller, int) {
305		contentError := func(line int, reason string) (*rollup.Roller, int) {
306			fmt.Fprintf(stderr, "rollupctl: %s:%d: %s\n", name, line, reason)
307			return nil, 4
308		}
309	
310		// The line buffer is capped at one byte over the limit, so a longer
311		// line fails immediately instead of growing with the file.
312		sc := bufio.NewScanner(in)
313		sc.Buffer(make([]byte, maxLineBytes+1), maxLineBytes+1)
314	
315		roller := rollup.New(d)
316		line := 0
317		samples := 0
318		for sc.Scan() {
319			line++
320			text := sc.Text()
321			if strings.TrimSpace(text) == "" {
322				continue
323			}
324			fields := strings.Fields(text)
325			if len(fields) != 2 {
326				return contentError(line, "expected a nanosecond timestamp and a value separated by whitespace")
327			}
328			ns, err := strconv.ParseInt(fields[0], 10, 64)
329			if err != nil {
330				return contentError(line, fmt.Sprintf("invalid timestamp %q", fields[0]))
331			}
332			value, err := strconv.ParseFloat(fields[1], 64)
333			if err != nil {
334				return contentError(line, fmt.Sprintf("invalid value %q", fields[1]))
335			}
336			if math.IsNaN(value) || math.IsInf(value, 0) {
337				return contentError(line, "value must be finite")
338			}
339			if err := roller.Add(time.Unix(0, ns).UTC(), value); err != nil {
340				return contentError(line, err.Error())
341			}
342			samples++
343		}
344		if err := sc.Err(); err != nil {
345			if errors.Is(err, bufio.ErrTooLong) {
346				// The over-long line is the one after every line already
347				// delivered, including an unterminated last line.
348				return contentError(line+1, "line is longer than 1024 bytes")
349			}
350			fmt.Fprintf(stderr, "rollupctl: %s: %v\n", name, err)
351			return nil, 3
352		}
353		if samples == 0 {
354			return contentError(0, "no samples found")
355		}
356		return roller, 0
357	}
358	
359	// formatFloat writes a float64 in its shortest round-trippable form; a
360	// negative zero keeps its sign and renders as -0.
361	func formatFloat(v float64) string {
362		return strconv.FormatFloat(v, 'g', -1, 64)
363	}
364	
365	var bigBillion = big.NewInt(1e9)
366	
367	// unixNanoText writes a window start as a signed integer count of
368	// nanoseconds since the epoch even when it falls outside the int64 range,
369	// so a start aligned past it is printed exactly instead of clamped.
370	func unixNanoText(t time.Time) string {
371		n := new(big.Int).Mul(big.NewInt(t.Unix()), bigBillion)
372		n.Add(n, big.NewInt(int64(t.Nanosecond())))
373		return n.String()
374	}
